INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56473, 0, 0, '|TInterface\\Icons\\inv_sword_24.blp:20|tFlying Snow uses her |cFFFF0000|Hspell:106706|h[Whirling Steel]|h|r technique!', 41, 0, 100, 0, 0, 0, 'Flying Snow');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56541, 0, 0, 'You!  You have allowed the Sha to reawaken after all these years!', 14, 0, 100, 0, 0, 27626, 'Master Snowdrift'),
(56541, 1, 0, 'If you truly wish to undo what your kind have wrought upon our land you must first prove yourselves here in our school.', 14, 0, 100, 0, 0, 27627, 'Master Snowdrift'),
(56541, 2, 0, 'First, you will face our initiates...', 14, 0, 100, 0, 0, 27632, 'Master Snowdrift'),
(56541, 3, 0, 'You have bested our most junior of students.  Now you will face two of my most senior.', 14, 0, 100, 0, 0, 27631, 'Master Snowdrift'),
(56541, 4, 0, 'Flying Snow!  Fragrant Lotus!  Step forward!', 14, 0, 100, 0, 0, 27636, 'Master Snowdrift'),
(56541, 5, 0, 'You have bested my prize students. Perhaps you can be of use to us after all...', 14, 0, 100, 0, 0, 27633, 'Master Snowdrift'),
(56541, 6, 0, 'As my master once said, \"You cannot truly know someone until you fight them.\"', 14, 0, 100, 0, 0, 27634, 'Master Snowdrift'),
(56541, 7, 0, 'Come forward, so that we may be properly introduced.', 14, 0, 100, 0, 0, 27635, 'Master Snowdrift'),
(56541, 8, 0, 'Very well then, outsiders. Let us see your true strength.', 14, 0, 100, 0, 0, 27628, 'Master Snowdrift'),
(56541, 9, 0, 'I am bested.  Give me a moment and we will venture forth together to face the Sha.', 14, 0, 100, 0, 0, 27623, 'Master Snowdrift'),
(56541, 10, 0, 'You need more training!', 14, 0, 100, 0, 0, 27637, 'Master Snowdrift'),
(56541, 10, 1, 'Your technique needs work.', 14, 0, 100, 0, 0, 27638, 'Master Snowdrift'),
(56541, 11, 0, 'Skill with a weapon is but a physical manifestation of one\'s martial strength. Let me show you what spiritual power is!', 14, 0, 100, 0, 0, 27629, 'Master Snowdrift'),
(56541, 12, 0, 'When I was but a cub I could scarcely throw a punch, but after years of training I can do so much more!', 14, 0, 100, 0, 0, 27630, 'Master Snowdrift'),
(56541, 13, 0, 'Where one falls, another will rise to take their place.', 14, 0, 100, 0, 0, 27624, 'Master Snowdrift'),
(56541, 13, 1, 'You have much to learn if you wish to defend your people from the Sha initiate.  Stand aside for your fellow students!', 14, 0, 100, 0, 0, 27625, 'Master Snowdrift');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56719, 0, 0, 'I will not be caged again. These Shado-Pan could not stop me. Neither shall you!', 14, 0, 100, 0, 0, 28346, 'Sha of Violence'),
(56719, 1, 0, 'So long as violence lurks in your hearts... I... will... return...', 14, 0, 100, 0, 0, 28347, 'Sha of Violence'),
(56719, 2, 0, 'Another violent death...', 14, 0, 100, 0, 0, 28348, 'Sha of Violence');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56747, 0, 0, 'Let me show you my power.', 12, 0, 100, 0, 0, 28317, 'Gu Cloudstrike'),
(56747, 1, 0, 'Come to me, serpent!  Together we will destroy these intruders.', 12, 0, 100, 0, 0, 28318, 'Gu Cloudstrike'),
(56747, 2, 0, 'Even together... we failed...', 14, 0, 100, 0, 0, 28319, 'Gu Cloudstrike'),
(56747, 3, 0, 'Their energy is strong!', 14, 0, 100, 0, 0, 28320, 'Gu Cloudstrike'),
(56747, 4, 0, 'No, no! Do not fail me!', 14, 0, 100, 0, 0, 28321, 'Gu Cloudstrike'),
(56747, 5, 0, 'Weaklings... let me make room for our guests.', 14, 0, 100, 0, 0, 28322, 'Gu Cloudstrike'),
(56747, 6, 0, 'Approach... your death awaits.', 14, 0, 100, 0, 0, 28323, 'Gu Cloudstrike'),
(56747, 7, 0, 'Serpent, charge me with your power!', 12, 0, 100, 0, 0, 28324, 'Gu Cloudstrike'),
(56747, 8, 0, 'Weakling!', 14, 0, 100, 0, 0, 28325, 'Gu Cloudstrike'),
(56747, 8, 1, 'Lightning has no mercy!', 14, 0, 100, 0, 0, 28326, 'Gu Cloudstrike');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(56884, 0, 0, 'Taran Zhu and the Shado-Pan are MINE. Come forward and die by my hand, as all who oppose me shall in the days to come!', 14, 0, 100, 0, 0, 28334, 'Corrupted Taran Zhu'),
(56884, 1, 0, 'Hatred will consume and conquer all!', 14, 0, 100, 0, 0, 28332, 'Corrupted Taran Zhu'),
(56884, 2, 0, 'No... NO!', 14, 0, 100, 0, 0, 28333, 'Corrupted Taran Zhu'),
(56884, 3, 0, 'Rage at your defeat.', 14, 0, 100, 0, 0, 28335, 'Corrupted Taran Zhu'),
(56884, 4, 0, 'The Sha of Hatred has fled my body... and the monastery, as well. I must thank you, strangers. The Shado-Pan are in your debt. Now, there is much work to be done...', 14, 0, 100, 0, 0, 28423, 'Corrupted Taran Zhu');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(59751, 0, 0, 'Brothers! Dispose of these insolent outsiders!', 14, 0, 100, 0, 0, 27746, 'Shado-Pan Warden'),
(59751, 0, 1, 'The Shado-Pan need no outside aid! Remove these interlopers!', 14, 0, 100, 0, 0, 27745, 'Shado-Pan Warden');
